// Gathers what the AI needs: the CV text (from the PDF) and the job requirements (from the candidate's Notion page).
// Stops with a clear message when something is missing, so nothing is scored on empty input.
const s = $('Settings').item.json;
const page = $('Settings').item.json; // the candidate page from Notion (the Settings node passes every Notion field on)
const norm = x => String(x).toLowerCase().replace(/[^a-z0-9]/g, '');
const find = name => { const k = Object.keys(page).find(k => norm(k) === norm(name) || norm(k) === norm('property ' + name)); return k ? page[k] : undefined; };
const pick = v => {
  if (v == null) return '';
  if (Array.isArray(v)) return v.map(pick).filter(Boolean).join('\n');
  if (typeof v === 'object') return pick(v.plain_text ?? v.text ?? v.content ?? v.name ?? v.title ?? '');
  return String(v).trim();
};
const cv = String($json.text || '').trim();
if (cv.length < 50) throw new Error('The CV PDF has no readable text (a scanned image?). Upload a text-based PDF, then set the status again.');
const jobText = pick(find('Job description'));
const jobTitle = pick(find('Job title'));
const jobUrl = pick(find('Job ad URL'));
const wantsApify = s.fetchJobAdWithApify === true && !!jobUrl;
if (!jobText && !wantsApify) throw new Error("No job requirements found. Fill the property 'Job description' on the candidate (text, or a rollup of the linked job page), or turn on fetchJobAdWithApify and fill 'Job ad URL'.");
const max = Number(s.maxCvChars) > 0 ? Number(s.maxCvChars) : 15000;
return { json: { cv: cv.slice(0, max), jobText, jobTitle, jobUrl, wantsApify,
  candidateName: pick(find('Name')), candidateEmail: pick(find('Email Address')), pageId: page.id } };

// Adds the fetched job ad text to the job requirements. A deactivated or empty Apify node passes the item through unchanged.
const base = $('Collect the CV and the job requirements').first().json; // the Apify option handles one candidate at a time
const ad = $input.all().map(i => i.json).find(j => j && String(j.description_text || '').trim());
if (!ad) {
  if (!base.jobText) throw new Error("job-feed returned no text for the 'Job ad URL', and 'Job description' is empty. Activate the Apify node and connect Apify, or fill 'Job description'.");
  return { json: base };
}
const jobText = [base.jobText, String(ad.description_text).trim()].filter(Boolean).join('\n\n');
return { json: { ...base, jobText: jobText.slice(0, 20000), jobTitle: base.jobTitle || String(ad.title || '') } };

// Builds the scoring prompt from the CV, the job requirements and your Settings.
const s = $('Settings').item.json;
const j = $json;
const lang = String(s.outputLanguage || '').trim() || 'English';
const extra = String(s.extraCriteria || '').trim();
const link = String(s.schedulingLink || '').trim();
const prompt = `You are a careful recruiting assistant. Compare the candidate's CV with the job requirements and return a structured screening result. A human recruiter makes every final decision: you only prepare it.

JOB (${j.jobTitle || 'title not given'}):
<job>
${j.jobText}
</job>

CV:
<cv>
${j.cv}
</cv>

RULES
- Use only facts that are in the CV and in the job text. Never invent skills, employers, degrees or dates. If something is not in the CV, say it is not shown.
- Do not use age, gender, nationality, marital status, photo, health or other protected traits. Judge skills, experience, education and language fit only.
- Write every text field in ${lang}.
${extra ? '- Extra instructions from the recruiter: ' + extra + '\n' : ''}
SCORING
- criteria: exactly these five, each with a score from 0 to 10 and a justification of 2-3 sentences: "Skills match", "Experience level", "Education", "Language fit", "Overall fit".
- overallScore: 0-100 for the whole fit (not an average you must compute: your holistic judgement).
- recommendation: "Strong match" (80-100), "Possible match" (60-79) or "Weak match" (0-59).
- proceed: true when overallScore is at least ${Number(s.minScore) || 70}, otherwise false.
- nextStep: "Interview" when proceed is true and overallScore is 80 or more, "Screening call" when proceed is true otherwise, "Reject" when proceed is false.
- summary: 3-4 sentences for the recruiter. strengths and gaps: up to 4 short items each. internalNote: one short sentence on what to check next.
- candidateName, candidateEmail, currentPosition: read from the CV ("" when not shown).

EMAIL DRAFT TO THE CANDIDATE (email.subject and email.body, plain text)
- Address the candidate by first name. Sign with "${s.recruiterName}, ${s.companyName}".
- proceed = true: thank them and invite them to the next step (the nextStep). ${link ? 'Offer this scheduling link: ' + link : 'Write [scheduling link] where a link belongs.'}
- proceed = false: a polite, respectful decline with one or two concrete, constructive points. Do not state scores.
- Do not promise a job, a salary or a date.`;
return { json: { ...j, prompt } };

// Takes the AI result, decides proceed from your minScore (the code decides, not the AI) and shapes the Notion update and the drafts.
const s = $('Settings').item.json;
const c = $('Collect the CV and the job requirements').item.json;
const o = $json.output || {};
const overall = Math.max(0, Math.min(100, Math.round(Number(o.overallScore) || 0)));
const min = Number(s.minScore) || 70;
const proceed = overall >= min;
const mismatch = !!o.proceed !== proceed;
const email = String(c.candidateEmail || o.candidateEmail || '').trim();
const name = String(c.candidateName || o.candidateName || '').trim();
const list = a => (Array.isArray(a) ? a : []).map(x => '- ' + x).join('
');
const crit = (Array.isArray(o.criteria) ? o.criteria : []).map(x => x.name + ' ' + x.score + '/10: ' + x.justification).join('
');
const cut = t => String(t || '').slice(0, 1900);
const note = (mismatch ? 'Check the email draft: the AI wrote it for ' + (o.proceed ? 'proceed' : 'reject') + ' but the score ' + overall + ' vs minScore ' + min + ' gives ' + (proceed ? 'proceed' : 'reject') + '. ' : '') + String(o.internalNote || '');
const job = c.jobTitle || 'the role';
return { json: {
  pageId: c.pageId, candidateName: name, candidateEmail: email, overallScore: overall, proceed, emailMismatch: mismatch,
  newStatus: proceed ? s.statusIfProceed : s.statusIfReject,
  summary: cut(String(o.summary || '') + '

Strengths:
' + list(o.strengths) + '

Gaps:
' + list(o.gaps)),
  internalNote: cut(note + '

' + crit),
  draftSubject: String((o.email && o.email.subject) || 'Your application'),
  draftBody: String((o.email && o.email.body) || ''),
  teamSubject: 'CV scoring: ' + (name || 'candidate') + ' for ' + job + ' (' + overall + '/100, ' + (proceed ? 'proceed' : 'reject') + ')',
  teamBody: 'Candidate: ' + name + '
Role: ' + job + '
Score: ' + overall + '/100 (' + (o.recommendation || '') + ')
Suggested next step: ' + (o.nextStep || '') + '

' + String(o.summary || '') + '

Strengths:
' + list(o.strengths) + '

Gaps:
' + list(o.gaps) + '

' + crit + '

This is an AI suggestion. A person decides.'
} };
